const raw = $input.first().json;
const body = raw.body || raw;
const data = body.data || body;
const key = (data && data.key) || (data && data.message && data.message.key) || {};

function saltar(motivo) { return [{ json: { procesar: false, motivo: motivo } }]; }

if (key.fromMe === true) return saltar('mensaje propio');

const jid = String(key.remoteJid || data.remoteJid || '');
if (!jid) return saltar('evento sin remoteJid');
if (jid.indexOf('@g.us') !== -1) return saltar('grupo');
if (jid.indexOf('@broadcast') !== -1 || jid.indexOf('@newsletter') !== -1) return saltar('difusion o canal');

// WhatsApp esta migrando a direccionamiento LID: en esos chats el remoteJid ya no es
// el telefono sino un identificador opaco de 15+ digitos. Cogerle los ultimos 9 y
// buscar por sufijo emparejaba con la captacion de OTRO propietario y le escribia
// el estado encima. Aqui se resuelve el telefono real o se descarta el evento.
let digits = '';
if (jid.indexOf('@lid') !== -1) {
  const alt = key.senderPn || key.remoteJidAlt || key.previousRemoteJid || '';
  digits = String(alt).split('@')[0].replace(/\D/g, '');
  if (!digits) return saltar('LID sin telefono resoluble: ' + jid);
} else if (jid.indexOf('@s.whatsapp.net') !== -1) {
  digits = jid.split('@')[0].replace(/\D/g, '');
} else {
  return saltar('jid no soportado: ' + jid);
}

if (digits.indexOf('00') === 0) digits = digits.slice(2);
if (digits.length === 9) digits = '34' + digits;

// Sin este corte, un sufijo vacio convertia el filtro en telefono=ilike.* (comodin)
// y el flujo clasificaba y pisaba una captacion cualquiera de la base.
if (!/^34[6-9]\d{8}$/.test(digits)) return saltar('telefono no valido: ' + digits);

return [{ json: { procesar: true, jid: jid, telefono: digits, sufijo: digits.slice(-9) } }];

const filas = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.id != null; });

if (!filas.length) return [{ json: { encontrada: false } }];

// Se piden 2 filas a proposito. Si un particular tiene dos anuncios con el mismo
// telefono no hay forma de saber por cual responde; el order de la consulta pone
// primera la contactada mas recientemente, que es la que provoco la respuesta.
const cap = filas[0];

return [{
  json: {
    encontrada: true,
    captacion_id: cap.id,
    nombre: cap.nombre,
    telefono: cap.telefono,
    estado_crm: cap.estado_crm,
    estado_whatsapp: cap.estado_whatsapp,
    ambigua: filas.length > 1,
    // Datos del inmueble, para el aviso por correo cuando hay interes
    barrio: cap.barrio || null,
    calle: cap.calle || null,
    precio: cap.precio || null,
    metros: cap.metros || null,
    habitaciones: cap.habitaciones || null,
    url: cap.url || null,
    operacion: cap.operacion || null,
    tipo: cap.tipo || null,
  },
}];

const webhook = $('Webhook Respuesta WA').first().json;
const wBody = webhook.body || webhook;
const wData = wBody.data || wBody;

// Los envoltorios de WhatsApp ANIDAN: en un chat con mensajes temporales, una foto
// de un solo uso llega como ephemeralMessage.message.viewOnceMessageV2.message.
// Por eso se desenvuelve en bucle y no con una cadena de ?? de un nivel.
function desenvolver(m) {
  let cur = m || {};
  for (let i = 0; i < 5; i++) {
    const w = cur.ephemeralMessage || cur.viewOnceMessage || cur.viewOnceMessageV2
      || cur.viewOnceMessageV2Extension || cur.documentWithCaptionMessage;
    if (!w || !w.message) break;
    cur = w.message;
  }
  return cur;
}

function texto(msg) {
  const m = desenvolver(msg);
  if (!m) return null;
  if (m.conversation) return m.conversation;
  if (m.extendedTextMessage && m.extendedTextMessage.text) return m.extendedTextMessage.text;
  if (m.imageMessage && m.imageMessage.caption) return m.imageMessage.caption;
  if (m.videoMessage && m.videoMessage.caption) return m.videoMessage.caption;
  if (m.documentMessage && m.documentMessage.caption) return m.documentMessage.caption;
  // La reaccion lleva el emoji en .text: un pulgar arriba es un 'si' que no hay que perder.
  if (m.reactionMessage && m.reactionMessage.text) return m.reactionMessage.text;
  if (m.buttonsResponseMessage && m.buttonsResponseMessage.selectedDisplayText) return m.buttonsResponseMessage.selectedDisplayText;
  if (m.listResponseMessage && m.listResponseMessage.title) return m.listResponseMessage.title;
  if (m.audioMessage) return '[nota de voz]';
  if (m.imageMessage) return '[foto]';
  if (m.videoMessage) return '[video]';
  if (m.documentMessage) return '[documento]';
  if (m.locationMessage) return '[ubicacion]';
  if (m.contactMessage || m.contactsArrayMessage) return '[contacto]';
  if (m.stickerMessage) return '[sticker]';
  return null;
}

const entrante = texto(wData.message);

// Historial de la conversacion. Si Evolution falla no se aborta: se clasifica el
// mensaje suelto, que es lo unico que hacia el flujo anterior de todas formas.
const registros = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const lista = (j.messages && j.messages.records) || j.records || (Array.isArray(j) ? j : []);
  if (Array.isArray(lista)) for (const m of lista) registros.push(m);
}

const hilo = registros
  .filter(function (m) { return m && m.key; })
  .map(function (m) {
    return {
      ts: Number(m.messageTimestamp || 0),
      quien: m.key.fromMe ? 'Agente' : 'Propietario',
      txt: texto(m.message),
    };
  })
  .filter(function (m) { return m.txt; })
  .sort(function (a, b) { return a.ts - b.ts; })
  .slice(-8);

const lineas = hilo.map(function (m) { return m.quien + ': ' + m.txt; });
const ultimo = entrante || (hilo.length ? hilo[hilo.length - 1].txt : null);

// Nunca se lanza un throw: perder la respuesta de un propietario por un tipo de
// mensaje raro es mucho peor que clasificarla como 'Respondido'.
if (!ultimo) {
  return [{ json: { conversacion: 'Propietario: [mensaje no textual]', ultimo: '[mensaje no textual]' } }];
}

if (!lineas.length || lineas[lineas.length - 1] !== 'Propietario: ' + ultimo) {
  lineas.push('Propietario: ' + ultimo);
}

return [{ json: { conversacion: lineas.join('\n'), ultimo: ultimo } }];

parameters.text:
=Conversacion de WhatsApp entre un agente inmobiliario y el propietario de un inmueble:

{{ $json.conversacion }}

Clasifica la intencion del propietario en su ultimo mensaje.

parameters.jsCode:
const salida = $input.first().json || {};
const bruto = String(salida.text || salida.output || '').trim();

const validos = ['No_Interesado', 'Interesado', 'Quiere_Llamada', 'Respondido'];
const clasificacion = validos.find(function (v) { return bruto === v; })
  || validos.find(function (v) { return bruto.indexOf(v) !== -1; })
  || 'Respondido';

const cap = $('Elegir Captacion').first().json;

// Un clasificador automatico no puede deshacer el trabajo del agente. Si la captacion
// ya avanzo mas alla de Contactado/Interesado (Propuesta, Negociacion, Ganado), solo
// se registra la senal de WhatsApp y se deja el estado del CRM como esta: un
// 'no, el jueves no puedo' en mitad de una negociacion no es una captacion perdida.
const WA_A_CRM = { Interesado: 'Interesado', Quiere_Llamada: 'Interesado', No_Interesado: 'Perdido' };
const EDITABLES = ['Nuevo', 'Contactado', 'Interesado', 'Perdido'];
const actual = cap.estado_crm || 'Nuevo';

const update = { estado_whatsapp: clasificacion };
let crmNuevo = null;
if (WA_A_CRM[clasificacion] && EDITABLES.indexOf(actual) !== -1) {
  crmNuevo = WA_A_CRM[clasificacion];
  update.estado_crm = crmNuevo;
}

const WA_A_LEAD = { Interesado: 'Interesado', Quiere_Llamada: 'Interesado', No_Interesado: 'Perdido', Respondido: 'Contactado' };

return [{
  json: {
    captacion_id: cap.captacion_id,
    nombre: cap.nombre || 'Propietario',
    telefono: cap.telefono,
    clasificacion: clasificacion,
    update: update,
    estado_crm_anterior: actual,
    estado_crm_nuevo: crmNuevo,
    estado_wa_anterior: cap.estado_whatsapp || null,
    lead_estado: WA_A_LEAD[clasificacion] || 'Contactado',
    ambigua: cap.ambigua === true,
  },
}];

const c = $('Aplicar Clasificacion').first().json;

// Se llega aqui cuando el PATCH por captacion_id no encontro ninguna fila: pasa
// siempre que el agente contacto a mano desde el CRM (esa via no creaba lead) y
// tambien si el 'Crear Lead' de la cola fallo. Sin esto la clasificacion se aplicaba
// a la captacion pero el propietario interesado no aparecia nunca en /leads.
return [{
  json: {
    nombre: c.nombre,
    telefono: c.telefono,
    fuente: 'Captaciones',
    estado: c.lead_estado,
    captacion_id: c.captacion_id,
    notas: 'Creado al clasificar la respuesta del propietario por WhatsApp',
  },
}];

// Aviso interno cuando un propietario se interesa. Se abre casi siempre desde el
// movil, asi que lo primero que se ve tiene que ser a quien hay que llamar y por
// que; la ficha del inmueble va debajo.
//
// Maquetado con tablas y estilos en linea a proposito: Outlook y el Gmail de
// Android ignoran flexbox, grid y las hojas de estilo, y el correo se desmontaria.
const a = $('Aplicar Clasificacion').first().json;
const c = $('Elegir Captacion').first().json;
let dijo = '';
try { dijo = String($('Montar Hilo').first().json.ultimo || '').trim(); } catch (e) { dijo = ''; }

// Escapar SIEMPRE: el nombre y la respuesta son texto escrito por un tercero.
function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function eur(n) { return n == null ? null : Number(n).toLocaleString('es-ES'); }

const TIPO = { homes: 'Vivienda', premises: 'Local', offices: 'Oficina', garages: 'Plaza de garaje', lands: 'Terreno', storageRooms: 'Trastero', rooms: 'Habitacion' };
const tipo = TIPO[c.tipo] || 'Inmueble';
const enAlquiler = c.operacion === 'rent';
const operacion = enAlquiler ? 'en alquiler' : 'en venta';
const zona = String(c.barrio || '').replace(/^(Sub)?[Dd]istrict /, '').trim();
const urgente = a.clasificacion === 'Quiere_Llamada';

// Ambar para el interes, rojo para quien pide expresamente que le llamen: se
// distinguen de un vistazo en la bandeja sin abrirlos.
const COLOR = urgente ? '#c0392b' : '#b8860b';
const ETIQUETA = urgente ? 'PIDE QUE LE LLAMEN' : 'PROPIETARIO INTERESADO';

const asunto = (urgente ? '\u260E PIDE QUE LE LLAMEN' : '\u2605 Propietario interesado') +
  ' \u00b7 ' + (a.nombre || 'sin nombre') + (zona ? ' (' + zona + ')' : '') +
  ' \u00b7 ' + tipo + ' ' + operacion;

// Solo las filas con dato: una ficha llena de 'no especificado' se lee peor y
// hace dudar de todo lo demas.
const filas = [
  ['Inmueble', esc(tipo + ' ' + operacion)],
  ['Direccion', c.calle ? esc(c.calle) : null],
  ['Zona', zona ? esc(zona) : null],
  ['Precio', eur(c.precio) ? '<strong>' + esc(eur(c.precio)) + ' \u20ac</strong>' + (enAlquiler ? '/mes' : '') : null],
  ['Superficie', c.metros ? esc(c.metros) + ' m\u00b2' : null],
  ['Habitaciones', c.habitaciones ? esc(c.habitaciones) : null],
  ['Anuncio', c.url ? '<a href="' + esc(c.url) + '" style="color:#1a5fb4">Ver en Idealista</a>' : null],
  ['Referencia', esc(a.captacion_id)],
].filter(function (f) { return f[1]; });

const tel = String(a.telefono || '').replace(/\D/g, '');
const telBonito = tel ? '+' + tel.replace(/^(\d{2})(\d{3})(\d{3})(\d{3})$/, '$1 $2 $3 $4') : '';

const html = [
  '<div style="background:#f4f5f7;padding:24px 12px;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif">',
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid #e3e5e8">',

  // Cabecera: de donde viene esto, sin lugar a dudas
  '<tr><td style="background:#1f2937;padding:14px 22px">',
  '<span style="color:#ffffff;font-size:15px;font-weight:700;letter-spacing:.2px">Grupo Hogares</span>',
  '<span style="color:#9ca3af;font-size:13px"> &nbsp;\u00b7&nbsp; Captador autom\u00e1tico de Idealista</span>',
  '</td></tr>',

  // Franja de estado
  '<tr><td style="background:' + COLOR + ';padding:9px 22px">',
  '<span style="color:#ffffff;font-size:12px;font-weight:700;letter-spacing:1.1px">' + ETIQUETA + '</span>',
  '</td></tr>',

  // Quien es y que ha dicho
  '<tr><td style="padding:22px 22px 6px">',
  '<div style="font-size:22px;font-weight:700;color:#111827;line-height:1.25">' + esc(a.nombre || 'Propietario') + '</div>',
  '<div style="font-size:13px;color:#6b7280;padding-top:3px">Ha respondido al primer WhatsApp del captador</div>',
  '</td></tr>',

  dijo ? '<tr><td style="padding:12px 22px 0">' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>' +
    '<td style="background:#f9fafb;border-left:3px solid ' + COLOR + ';padding:12px 14px;border-radius:0 6px 6px 0">' +
    '<span style="font-size:15px;color:#1f2937;font-style:italic">\u201c' + esc(dijo) + '\u201d</span>' +
    '</td></tr></table></td></tr>' : '',

  // El boton de llamar, que es lo que se viene a hacer
  tel ? '<tr><td style="padding:18px 22px 4px">' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>' +
    '<td style="background:#16a34a;border-radius:7px">' +
    '<a href="tel:+' + esc(tel) + '" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:16px;font-weight:700;text-decoration:none">Llamar a ' + esc(telBonito) + '</a>' +
    '</td><td style="width:10px"></td>' +
    '<td style="border:1px solid #d1d5db;border-radius:7px">' +
    '<a href="https://wa.me/' + esc(tel) + '" style="display:inline-block;padding:12px 18px;color:#374151;font-size:15px;font-weight:600;text-decoration:none">WhatsApp</a>' +
    '</td></tr></table></td></tr>' : '',

  // La ficha
  '<tr><td style="padding:18px 22px 4px">',
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse;font-size:14px">',
  filas.map(function (f, i) {
    const linea = i ? 'border-top:1px solid #f0f1f3;' : '';
    return '<tr>' +
      '<td style="' + linea + 'padding:9px 14px 9px 0;color:#6b7280;white-space:nowrap;vertical-align:top;width:34%">' + f[0] + '</td>' +
      '<td style="' + linea + 'padding:9px 0;color:#111827">' + f[1] + '</td></tr>';
  }).join(''),
  '</table></td></tr>',

  // Pie
  '<tr><td style="padding:16px 22px 20px">',
  '<div style="border-top:1px solid #eef0f2;padding-top:12px;font-size:12px;color:#9ca3af;line-height:1.5">',
  'Mensaje autom\u00e1tico del <strong style="color:#6b7280">captador de Idealista</strong>. Se env\u00eda solo cuando la respuesta de un propietario se clasifica como <strong style="color:#6b7280">Interesado</strong> o <strong style="color:#6b7280">Quiere llamada</strong>.<br>El bot no sigue la conversaci\u00f3n: a partir de aqu\u00ed la lleva una persona.',
  '</div></td></tr>',

  '</table></div>',
].join('');

return [{ json: { asunto: asunto, html: html, captacion_id: a.captacion_id, clasificacion: a.clasificacion } }];
